import React, { useEffect, useState } from "react";
import "./weather.css";

export default function Weather() {
  const [data, setData] = useState(null);
  const [humidity, setHumidity] = useState(null);

  const lat = 34.68;
  const lon = -1.91;

  useEffect(() => {
    const fetchWeather = async () => {
      try {
        const res = await fetch(
          `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current_weather=true&hourly=relativehumidity_2m`
        );
        const weatherData = await res.json();

        setData(weatherData.current_weather);

        // جلب الرطوبة حسب نفس توقيت current_weather
        const index = weatherData.hourly.time.indexOf(weatherData.current_weather.time);
        setHumidity(weatherData.hourly.relativehumidity_2m[index]);

      } catch (err) {
        console.log(err);
      }
    };

    fetchWeather();
  }, []);

  if (!data) return <h2 className="loading">Loading Weather...</h2>;

  return (
    <div className="weather-container">
      <div className="weather-card">

        <h2 className="city">Oujda - Morocco</h2>

        <div className="main">
          <h1 className="temp">{Math.round(data.temperature)}°C</h1>

          <p className="desc">
            {weatherCodeToText(data.weathercode)}
          </p>
        </div>

        <div className="details">
          <div>
            <h4>Feels Like</h4>
            <p>{Math.round(data.temperature - 1)}°C</p>
          </div>

          <div>
            <h4>Humidity</h4>
            <p>{humidity}%</p>
          </div>

          <div>
            <h4>Wind</h4>
            <p>{data.windspeed} km/h</p>
          </div>
        </div>

        <p className="time">
          {data.time.replace("T", "  ")}
        </p>
      </div>
    </div>
  );
}


// ترجمة weather codes
function weatherCodeToText(code) {
  const codes = {
    0: "Clear Sky",
    1: "Mainly Clear",
    2: "Partly Cloudy",
    3: "Cloudy",
    45: "Fog",
    48: "Freezing Fog",
    51: "Light Drizzle",
    61: "Rain",
    71: "Snow",
    95: "Thunderstorm",
  };

  return codes[code] || "Weather Info";
}
